teralContent":true},"optimizer":{"enabled":true,"runs":200},"remappings":[]},"sources":{"src/contracts/ElectronicVoting.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

interface ICircuitValidator {
    function verify(uint256[] memory input, uint256[2] memory a, uint256[2][2] memory b, uint256[2] memory c) external view returns (bool);
}

contract ElectronicVoting {
    struct Candidate {
        uint256 id;
        string name;
        uint256 voteCount;
    }

    struct Election {
        uint256 id;
        string name;
        uint256 startTime;
        uint256 endTime;
        bool isActive;
        string credentialSchema;
        string credentialQuery;
        address validator;
    }

    address public admin;
    uint256 public electionCount;

    mapping(uint256 => Election) public elections;
    mapping(uint256 => Candidate[]) public electionCandidates;
    mapping(uint256 => mapping(address => bool)) public hasVoted;
    mapping(uint256 => mapping(address => bool)) public invited;
    mapping(uint256 => mapping(address => bool)) public claimed;

    // Validator trên Amoy
    address public constant AMOY_VALIDATOR = 0xb1e86C4c687B85520eF4fd2a0d14e81970a15aFB;

    event ElectionCreated(uint256 indexed electionId, string name);
    event Voted(uint256 indexed electionId, address indexed voter, uint256 candidateId);
    event VoterInvited(uint256 indexed electionId, address indexed voter);
    event VoterClaimed(uint256 indexed electionId, address indexed voter);

    constructor() {
        admin = msg.sender;
    }

    function createElection(
        string memory _name, 
        string[] memory _candidateNames,
        string memory _credentialSchema,
        string memory _credentialQuery,
        uint256 _durationInMinutes
    ) public {
        require(msg.sender == admin, "Only admin");
        electionCount++;
        uint256 newId = electionCount;

        elections[newId] = Election({
            id: newId,
            name: _name,
            startTime: block.timestamp,
            endTime: block.timestamp + (_durationInMinutes * 1 minutes),
            isActive: true,
            credentialSchema: _credentialSchema,
            credentialQuery: _credentialQuery,
            validator: AMOY_VALIDATOR
        });

        for (uint256 i = 0; i < _candidateNames.length; i++) {
            electionCandidates[newId].push(Candidate({
                id: i,
                name: _candidateNames[i],
                voteCount: 0
            }));
        }

        emit ElectionCreated(newId, _name);
    }

    function inviteVoters(uint256 _electionId, address[] calldata _voters) public {
        require(msg.sender == admin, "Only admin");
        for (uint256 i = 0; i < _voters.length; i++) {
            invited[_electionId][_voters[i]] = true;
            emit VoterInvited(_electionId, _voters[i]);
        }
    }

    function claim(uint256 _electionId) public {
        require(invited[_electionId][msg.sender], "Not invited");
        require(!claimed[_electionId][msg.sender], "Already claimed");
        claimed[_electionId][msg.sender] = true;
        emit VoterClaimed(_electionId, msg.sender);
    }

    function vote(
        uint256 _electionId, 
        uint256 _candidateId,
        uint256[2] memory a,
        uint256[2][2] memory b,
        uint256[2] memory c,
        uint256[] memory input
    ) public {
        Election storage election = elections[_electionId];
        require(election.isActive, "Closed");
        require(block.timestamp <= election.endTime, "Ended");
        require(!hasVoted[_electionId][msg.sender], "Voted");
        require(claimed[_electionId][msg.sender], "Credential not claimed");

        ICircuitValidator validatorContract = ICircuitValidator(election.validator);
        require(validatorContract.verify(input, a, b, c), "ZK Invalid");

        hasVoted[_electionId][msg.sender] = true;
        electionCandidates[_electionId][_candidateId].voteCount++;

        emit Voted(_electionId, msg.sender, _candidateId);
    }

    function getCandidates(uint256 _electionId) public view returns (Candidate[] memory) {
        return electionCandidates[_electionId];
    }
    
    function getElection(uint256 _electionId) public view returns (Election memory) {
        return elections[_electionId];
    }
}","keccak256":"0x71a747084fc002b45a5f1e25d7e492339cc9fb2a42b96f23e34a7515580eb60a","license":"MIT"}},"version":1}

